{
  "rules": [
    {
      "id": "D_LIMIT_MULTIPLE_OF_10000",
      "description": "Credit limits should be multiples of 10,000.",
      "gx_code": "gx.expect_column_values_to_be_in_set(column='LIMIT_BAL', value_set=[0, 10000, 20000, 30000, 40000, 50000, 60000, 70000, 80000, 90000, 100000, 110000, 120000, 130000, 140000, 150000, 160000, 170000, 180000, 190000, 200000, 210000, 220000, 230000, 240000, 250000, 260000, 270000, 280000, 290000, 300000])",
      "evidence_references": ["D_LIMIT_GRANULARITY"]
    },
    {
      "id": "D_PAY_AMT_NONNEG",
      "description": "Payment amounts should be non-negative.",
      "gx_code": "gx.expect_column_values_to_be_nonnegative(column='PAY_AMT1')",
      "evidence_references": ["D_PAY_AMT{i}_NONNEG"]
    },
    {
      "id": "D_BILL_AMT1_TO_LIMIT_BAL",
      "description": "Bill amount should not exceed 1.5 times the credit limit.",
      "gx_code": "gx.expect_column_values_to_be_between(column='BILL_AMT1', min_value=-1.5 * column('LIMIT_BAL'), max_value=1.5 * column('LIMIT_BAL'))",
      "evidence_references": ["D_BILL_OVER_LIMIT"]
    },
    {
      "id": "D_AGE_RANGE",
      "description": "Age should be within a reasonable range.",
      "gx_code": "gx.expect_column_values_to_be_between(column='AGE', min_value=18, max_value=100)",
      "evidence_references": ["D_AGE_RANGE"]
    }
  ],
  "abstentions": [
    "D_EDUCATION_DOCUMENTED",
    "D_BILL_OVER_LIMIT"
  ]
}
